function doorThumbnailTone(hex,factor){return '#'+hex.slice(1).match(/../g).map(v=>Math.min(255,Math.round(parseInt(v,16)*factor)).toString(16).padStart(2,'0')).join('');}
function colorDoorThumbnail(name,value,c){
 let svg=doorThumbnailArt[name];if(!svg)return './'+name+'.svg';
 const paints={White:'#ffffff',...paintColors,...stainColors,Sage:paintColors['Sage Green'],Slate:paintColors['Web Grey']};
 const siding=c.style==='Silver Bullet'?{...bulletStandard,...bulletPremium,Galvalume:metalRoofColors.Galvalume}:paints;
 const body=whiteOnlyDoor(value)?'#ffffff':paints[c.doorColor]||siding[c.color]||paints.Blue;
 const wooden=['Single','Double','Shed Door w/Transom','Double Shed Door w/ Transom'].includes(value);
 const trim=wooden?(paints[c.doorTrimColor]||paints[c.trimColor]||paints['Origami White']):body;
 svg=svg.replace(/<linearGradient id="(wood|panel|metal|trim)"[^>]*>[\s\S]*?<\/linearGradient>/g,(gradient,id)=>{
  const color=id==='trim'?trim:body;return gradient.replace(/stop-color="#[^"]+"/g,()=> 'stop-color="'+color+'"').replace(/(<stop offset="1" stop-color=")[^"]+/, '$1'+doorThumbnailTone(color,.88));
 });
 svg=svg.replaceAll('#827d74',doorThumbnailTone(body,.65)).replaceAll('#b8b1a5',doorThumbnailTone(body,1.14));
 return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);
}
function syncDoorThumbnails(){document.querySelectorAll('img[data-door-thumbnail]').forEach(img=>img.src=doorThumbnail(img.dataset.doorThumbnail));}
